perl -e '
use strict; use warnings;
my $root="/bench/repo";
my @entities = qw(User Memo Attachment Reaction Inbox MemoShare MemoRelation IdentityProvider UserIdentity UserSetting InstanceSetting);
sub pkg_of_file {
  my ($f)=@_; open my $fh,"<",$f or return "";
  my $p=""; while(<$fh>){ if(/^package (\S+)/){$p=$1; last} } close $fh;
  # use directory as package id for uniqueness
  (my $dir=$f)=~s|/[^/]+$||; $dir=~s|^\Q$root/\E||;
  return $dir;
}
sub walk { my ($d,$cb)=@_; return unless -d $d; opendir my $dh,$d or return; while(my $e=readdir $dh){ next if $e eq "."||".."; my $p="$d/$e"; -d $p ? walk($p,$cb) : $cb->($p) if -f $p } }
my @files; walk($root, sub { push @files, shift if $_[0]=~/\.go$/ });
my %counts;
for my $ent (@entities) {
  my %pkgs;
  for my $f (@files) {
    next if $f=~/^$root\/store\//; # outside store layer only
    open my $fh,"<",$f or next; local $/; my $c=<$fh>; close $fh;
    next unless $c=~/\bstore\.$ent\b|\*store\.$ent\b|\[\]\*store\.$ent\b/;
    my $pkg=pkg_of_file($f);
    $pkgs{$pkg}=1 if $pkg;
  }
  $counts{$ent}=scalar keys %pkgs;
}
my @rank = sort { $counts{$b} <=> $counts{$a} || $a cmp $b } @entities;
for my $e (@rank) {
  printf "%2d  store.%s\n", $counts{$e}, $e;
}
print "\nTop User packages:\n";
# detail top type
my $ent=$rank[0]; my %pkgs;
for my $f (@files) {
  next if $f=~/^$root\/store\//;
  open my $fh,"<",$f or next; local $/; my $c=<$fh>; close $fh;
  next unless $c=~/\bstore\.$ent\b|\*store\.$ent\b|\[\]\*store\.$ent\b/;
  my $pkg=pkg_of_file($f); $pkgs{$pkg}=1 if $pkg;
}
print "$_\n" for sort keys %pkgs;
'

