my @files = `find $root -name "*.go"`;
chomp @files;
my %counts; my %detail;
for my $ent (@entities) {
  my %pkgs;
  for my $f (@files) {
    next if $f=~/^$root\/store\//;
    open my $fh,"<",$f or next; local $/; my $c=<$fh>; close $fh;
    next unless $c=~/\bstore\.$ent\b/;
    (my $dir=$f)=~s|/[^/]+$||;
    $dir=~s|^\Q$root/\E||;
    $pkgs{$dir}=1;
  }
  $counts{$ent}=scalar keys %pkgs;
  $detail{$ent}=\%pkgs;
}
my @rank = sort { $counts{$b} <=> $counts{$a} || $a cmp $b } @entities;
for my $e (@rank) {
  printf "%2d  store.%s\n", $counts{$e}, $e;
}
for my $e (@rank[0,1]) {
  print "\n=== $e ($counts{$e}) ===\n";
  print "$_\n" for sort keys %{$detail{$e}};
}
'

